// SaaS CRM Lead Scoring, Segmentation & Churn Risk Engine
const u = $json;
const isPro = (u.plan || 'free') === 'pro';
let score = 35;
if (isPro) score += 45;
if (u.injuries && u.injuries.length > 0) score += 10;
if (u.diet && u.diet !== 'none') score += 10;
if (u.today_workout && !u.today_workout.toLowerCase().includes('rest')) score += 10;
score = Math.min(score, 100);

let segment = 'NURTURE';
let next_action = 'Encourage first Muscle Map workout';
let status = 'Onboarding';
let cta_label = 'Open Interactive Muscle Map';
let cta_url = 'https://gymbuddy-ai-phi.vercel.app/';

if (isPro) {
  segment = 'VIP_PRO';
  next_action = 'Deliver VIP coaching + Smart Chrono link';
  status = 'Active Pro';
  cta_label = 'Launch Pro In-Gym Chrono';
  cta_url = 'https://gymbuddy-ai-phi.vercel.app/gym';
} else if (score >= 55) {
  segment = 'HOT_LEAD';
  next_action = 'Offer Pro Smart Chrono & Equipment Scanner';
  status = 'Trial Eligible';
  cta_label = 'Try GymBuddy Pro Free';
  cta_url = 'https://gymbuddy-ai-phi.vercel.app/pricing';
}

const churn_risk = isPro ? 'Low' : (score >= 55 ? 'Medium' : 'Medium');

return {
  json: {
    ...u,
    plan: u.plan || 'free',
    segment,
    lead_score: score,
    churn_risk,
    status,
    next_action,
    cta_label,
    cta_url,
    last_contacted: new Date().toISOString()
  }
};

// Build a Metrya-branded HTML email (dark forest #08130D + electric lime #DAF85A) with safe fallback
const user = $('CRM Lead Scoring & Segmentation').item.json;
const aiText = $json.choices?.[0]?.message?.content;
const fallback = `Hi ${user.name || 'Athlete'},\n\nToday's workout: ${user.today_workout} (${user.equipment}).\nTargets: ${user.calories} kcal · ${user.protein_g}g protein · ${user.water_l}L water.\nStay consistent — small steps every day!`;
const bodyText = (aiText || fallback).trim();
const bodyHtml = bodyText.replace(/\n/g, '<br/>');

const html = `
<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;background:#F3F7F2;padding:24px;">
  <div style="max-width:560px;margin:0 auto;background:#FFFFFF;border-radius:24px;overflow:hidden;border:1px solid rgba(13,25,18,0.08);">
    <div style="background:#08130D;padding:24px 28px;color:#FFFFFF;">
      <span style="display:inline-block;background:#DAF85A;color:#0C3A22;font-size:11px;font-weight:800;padding:4px 10px;border-radius:999px;letter-spacing:0.08em;">${user.segment.replace('_',' ')}</span>
      <h1 style="margin:12px 0 4px;font-size:22px;color:#FFFFFF;">GymBuddy Daily Brief</h1>
      <p style="margin:0;font-size:13px;color:#A8BCB0;">Today: <strong style="color:#DAF85A;">${user.today_workout}</strong></p>
    </div>
    <div style="padding:24px 28px;color:#0D1912;font-size:14px;line-height:1.65;">
      <p style="margin-top:0;">${bodyHtml}</p>
      <div style="display:flex;gap:12px;margin:20px 0;padding:14px;background:#F3F7F2;border-radius:16px;font-size:12px;">
        <div><strong>${user.calories}</strong> kcal</div>
        <div>· <strong>${user.protein_g}g</strong> protein</div>
        <div>· <strong>${user.water_l}L</strong> water</div>
      </div>
      <a href="${user.cta_url}" style="display:inline-block;background:#0C3A22;color:#DAF85A;text-decoration:none;font-weight:700;padding:12px 22px;border-radius:999px;font-size:13px;">${user.cta_label} →</a>
    </div>
  </div>
</div>`;

return {
  json: {
    email: user.email,
    name: user.name || 'Athlete',
    segment: user.segment,
    lead_score: user.lead_score,
    subject: `[GymBuddy] ${user.today_workout} — Your Daily Coaching Plan`,
    body_text: bodyText,
    body_html: html,
    used_ai: Boolean(aiText),
    sent_at: new Date().toISOString()
  }
};

const sent = $input.all();
let stats = {};
try { stats = $('Fetch SaaS Platform KPIs').first().json; } catch {}
const bySegment = { VIP_PRO: 0, HOT_LEAD: 0, NURTURE: 0 };
let aiCount = 0;
for (const item of sent) {
  const seg = item.json.segment || 'NURTURE';
  bySegment[seg] = (bySegment[seg] || 0) + 1;
  if (item.json.used_ai) aiCount++;
}
return [{
  json: {
    run_date: new Date().toISOString(),
    emails_sent: sent.length,
    ai_success_rate: sent.length ? Math.round(100 * aiCount / sent.length) + '%' : '0%',
    segments: bySegment,
    total_users: stats.users ?? 'n/a',
    thumbs_up: stats.thumbs_up ?? 0,
    thumbs_down: stats.thumbs_down ?? 0,
    open_bug_reports: (stats.feedback || []).length
  }
}];

